/* @lc app=leetcode id=1834 lang=kotlin */ class Solution { fun getOrder(tasks: Array<IntArray>): IntArray = tasks.indices.sortedBy { tasks[it][0] }.let { o -> java.util.PriorityQueue<Int>(compareBy<Int>({ tasks[it][1] }, { it })).let { pq -> generateSequence(Triple(0L, 0, -1)) { (t, p, _) -> (if (pq.isEmpty() && p < o.size) maxOf(t, tasks[o[p]][0].toLong()) else t).let { t2 -> (p + generateSequence(p) { it + 1 }.takeWhile { it < o.size && tasks[o[it]][0] <= t2 }.onEach { pq.add(o[it]) }.count()).let { p2 -> if (pq.isEmpty()) null else pq.poll().let { idx -> Triple(t2 + tasks[idx][1], p2, idx) } } } }.drop(1).map { it.third }.toList().toIntArray() } } }